êÅ•ÿπÖç—•Ÿî4(ÄÄÄÅ©Ω•∏Å¡’â±•åπ•πŸïπ—Ω…Â}•—ïµÃÅ§ÅΩ∏Å§π•êı•ÿπ•—ïµ}•êÅÖπêÅ§πΩ…ùÖπ•ÈÖ—•Ωπ}•êı•ÿπΩ…ùÖπ•ÈÖ—•Ωπ}•êÅÖπêÅ§πÖç—•Ÿî4(ÄÄÄÅ›°ï…îÅ»πΩ…ùÖπ•ÈÖ—•Ωπ}•êıŸ}Ω…úÅÖπêÅ»πçÖ—Ö±Ωù}¡…Ωë’ç—}•êıπï‹πçÖ—Ö±Ωù}¡…Ωë’ç—}•ê4(ÄÄÄÄÄÅÖπêÅ»πâ…Öπç°}•êıŸ}ÕÖ±îπâ…Öπç°}•êÅÖπêÅ»πÖç—•Ÿî4(ÄÄÄÅΩ…ëï»Åâ‰Å»π•ê4(ÄÅ±ΩΩ¿4(ÄÄÄÅ•òÅπï‹πŸÖ…•Öπ—}•êÅ•ÃÅπΩ–Åπ’±∞ÅÖπêÅπï‹πŸÖ…•Öπ—}•êıŸ}…ïç•¡îπ•πŸïπ—Ω…Â}ŸÖ…•Öπ—}•êÅ—°ï∏4(ÄÄÄÄÄÅ…Ö•ÕîÅï·çï¡—•Ω∏Äù∞Åµ•ÕµºÅÖ…”µç’±ºÅïÕ”ÑÅŸ•πç’±ÖëºÅçΩµºÅ¡…Ωë’ç—ºÅŸïπë•ëºÅ‰ÅµÖ—ï…•Ö∞ÅçΩπÕ’µ•ëº∏ÅIïŸ•ÕÑÅï∞Å€µπç’±ºÅëîÅ•πŸïπ—Ö…•º∏úÏ4(ÄÄÄÅïπêÅ•òÏ4(ÄÄÄÅ•òÅŸ}…ïç•¡îπçÖ±ç’±Ö—•Ωπ}µΩëîÙù¡ï…}â•±±ïë}’π•–úÅ—°ï∏4(ÄÄÄÄÄÅŸ}…ï≈’•…ïêÄËÙÅçï•∞†°πï‹π≈’Öπ—•—‰©Ÿ}…ïç•¡îπ≈’Öπ—•—Â}¡ï…}âÖÕ•Ã§®ƒ¿¿¿§ºƒ¿¿¿Ï4(ÄÄÄÅï±Õî4(ÄÄÄÄÄÅŸ}›•ë—°}ç¥ÄËÙÅπ’±±•ò°Ÿ}…ïç•¡îπÖ——…•â’—ïÃ¥¯¯ù›•ë—°}ç¥ú∞úú§ËÈπ’µï…•åÏ4(ÄÄÄÄÄÅ•òÅŸ}›•ë—°}ç¥Å•ÃÅπ’±∞ÅΩ»ÅŸ}›•ë—°}ç¥Ù¿Å—°ï∏4(ÄÄÄÄÄÄÄÅ…Ö•ÕîÅï·çï¡—•Ω∏Äù1ÑÅ…ïçï—ÑÅ¡Ω»ÉÖ…ïÑÅπïçïÕ•—ÑÅ’πÑÅŸÖ…•Öπ—îÅëîÅ…Ω±±ºÅçΩ∏ÅÖπç°ºÅçΩπô•…µÖëº∏úÏ4(ÄÄÄÄÄÅïπêÅ•òÏ4(ÄÄÄÄÄÅ•òÅ±Ω›ï»°Ÿ}…ïç•¡îπâÖÕï}’π•–§ÅπΩ–Å•∏Ä†ùµï—…ºú∞ùµï—…ΩÃú∞ù¥ú∞ù¥Å±•πïÖ∞ú∞ùµï—…ºÅ±•πïÖ∞ú§Å—°ï∏4(ÄÄÄÄÄÄÄÅ…Ö•ÕîÅï·çï¡—•Ω∏Äù1ÑÅÕÖ±•ëÑÅëîÅ’πÑÅ…ïçï—ÑÅ¡Ω»ÉÖ…ïÑÅ…ï≈’•ï…îÅ’∏ÅµÖ—ï…•Ö∞ÅçΩπ—ÖëºÅï∏Åµï—…ΩÃÅ±•πïÖ±ïÃ∏úÏ4(ÄÄÄÄÄÅïπêÅ•òÏ4(ÄÄÄÄÄÅŸ}…ï≈’•…ïêÄËÙÅçï•∞†°πï‹π≈’Öπ—•—‰º°Ÿ}›•ë—°}ç¥ºƒ¿¿§©Ÿ}…ïç•¡îπ≈’Öπ—•—Â}¡ï…}âÖÕ•Ã®†ƒ≠Ÿ}…ïç•¡îπ›ÖÕ—ï}¡ï…çïπ–ºƒ¿¿§§®ƒ¿¿¿§ºƒ¿¿¿Ï4(ÄÄÄÅïπêÅ•òÏ4(ÄÄÄÅ•òÅŸ}…ï≈’•…ïêÙ¿Å—°ï∏ÅçΩπ—•π’îÏÅïπêÅ•òÏ4(ÄÄÄÅŸ}±ΩçÖ—•Ω∏ÄËÙÅçΩÖ±ïÕçî°π’±±•ò°Ÿ}…ïç•¡îπ±ΩçÖ—•Ωπ}çΩëî∞úú§∞ù5%8ú§Ï4(ÄÄÄÅ¡ï…ôΩ…¥ÄƒÅô…Ω¥Å¡’â±•åπ•πŸïπ—Ω…Â}ŸÖ…•Öπ—ÃÅ›°ï…îÅ•êıŸ}…ïç•¡îπ•πŸïπ—Ω…Â}ŸÖ…•Öπ—}•êÅÖπêÅΩ…ùÖπ•ÈÖ—•Ωπ}•êıŸ}Ω…úÅôΩ»Å’¡ëÖ—îÏ4(ÄÄÄÅÕï±ïç–ÅçΩÖ±ïÕçî°Õ’¥°Ãπ«m˜Í⁄$z{-ÆÈ‹j◊ùess','quality_review','ready','completed')
     and old.status not in ('in_progress','quality_review','ready','completed') then
    for v_component in select * from public.sale_material_consumptions c
      where c.organization_id=new.organization_id and c.sale_id=new.sale_id and c.reserved_quantity>0
      for update
    loop
      v_previous_reserved := v_component.reserved_quantity;
      update public.inventory_stock s set reserved_quantity=s.reserved_quantity-v_previous_reserved,updated_at=now()
        where s.organization_id=v_component.organization_id and s.variant_id=v_component.variant_id
          and s.branch_id=v_component.branch_id and s.location_code=v_component.location_code
          and s.reserved_quantity>=v_previous_reserved;
      if not found then raise exception 'No se pudo liberar la reserva del material de producci√≥n.'; end if;
      insert into public.inventory_reservation_audits
        (organization_id,variant_id,branch_id,location_code,previous_quantity,reserved_quantity,note,changed_by)
      values (v_component.organization_id,v_component.variant_id,v_component.branch_id,v_component.location_code,
        v_previous_reserved,(select s.reserved_quantity from public.inventory_stock s where s.organization_id=v_component.organization_id and s.variant_id=v_component.variant_id and s.branch_id=v_component.branch_id and s.location_code=v_component.location_code),
        'Consumo al iniciar producci√≥n '||new.order_code,v_user);
      insert into public.inventory_movements
        (organization_id,variant_id,branch_id,location_code,movement_type,quantity_delta,reason,reference_type,reference_id,created_by)
      values (v_component.organization_id,v_component.variant_id,v_component.branch_id,v_component.location_code,'consumption',-v_previous_reserved,
        'Consumo reservado de orden de producci√≥n '||new.order_code,'sale',new.sale_id,v_user);
      update public.sale_material_consumptions c set
        fulfilled_quantity=c.fulfilled_quantity+v_previous_reserved,
        reserved_quantity=0,
        status=case when c.backordered_quantity>0 then 'backordered' else 'consumed' end
      where c.id=v_component.id;
    end loop;
  elsif new.status='cancelled' and old.status not in ('completed','cancelled') then
    for v_component in select * from public.sale_material_consumptions c
      where c.organization_id=new.organization_id and c.sale_id=new.sale_id
        and (c.reserved_quantity>0 or c.backordered_quantity>0)
      for update
    loop
      v_previous_reserved := v_component.reserved_quantity;
      if v_previous_reserved>0 then
        update public.inventory_stock s set reserved_quantity=s.reserved_quantity-v_previous_reserved,updated_at=now()
          where s.organization_id=v_component.organization_id and s.variant_id=v_component.variant_id
            and s.branch_id=v_component.branch_id and s.location_code=v_component.location_code
            and s.reserved_quantity>=v_previous_reserved;
        if not found then raise exception 'No se pudo liberar la reserva de la orden cancelada.'; end if;
        insert into public.inventory_reservation_audits
          (organization_id,variant_id,branch_id,location_code,previous_quantity,reserved_quantity,note,changed_by)
        values (v_component.organization_id,v_component.variant_id,v_component.branch_id,v_component.location_code,
          v_previous_reserved,(select s.reserved_quantity from public.inventory_stock s where s.organization_id=v_component.organization_id and s.variant_id=v_component.variant_id and s.branch_id=v_component.branch_id and s.location_code=v_component.location_code),
          'Liberaci√≥n por cancelaci√≥n de producci√≥n '||new.order_code,v_user);
      end if;
      update public.sale_material_consumptions c set
        released_quantity=c.released_quantity+c.reserved_quantity+c.backordered_quantity,
        reserved_quantity=0,backordered_quantity=0,status='released'
      where c.id=v_component.id;
    end loop;
  end if;
  return new;
end;
$function$;
revoke all on function app_private.settle_sale_material_reservations() from public,anon,authenticated;
create trigger production_order_settle_materials
  after update of status on public.production_orders
  for each row execute function app_private.settle_sale_material_reservations();

-- Register the two catalog accessories as tracked units in Visual Corp.
-- No inventory_stock row is inserted: the team must physically count first.
with org as (
  select id from public.organizations where slug='visual-corp'
), specs(sku,name,catalog_id) as (
  values
    ('VC-INV-ACC-OJAL-PEQ','Ojal peque√±o','prod-extras-ojal-peque-o-c-u'),
    ('VC-INV-ACC-OJAL-GDE','Ojal grande','prod-extras-ojales-grande-c-u')
)
insert into public.inventory_items
  (organization_id,category_id,area_id,sku,name,description,item_type,tags,reference_image_url,custom_fields,base_unit,minimum_quantity,active)
select org.id,cat.id,area.id,specs.sku,specs.name,
  'Accesorio de confecci√≥n. Conteo f√≠sico inicial pendiente.', 'consumible', array['ojales','acabados'],
  '/inventory/grommets-reference.webp',
  jsonb_build_object(
    'source_status','count_pending',
    'stock_count_required',true,
    'image_source','generated_reference',
    'initial_branch_id',branch.id,
    'default_location_code','MAIN'
  ),
  'unidad',0,true
from org cross join specs
join public.inventory_categories cat on cat.organization_id=org.id and cat.code='CAT-TRO-ACABADOS'
join public.areas area on area.organization_id=org.id and area.code='TRO'
join public.branches branch on branch.organization_id=org.id and branch.code='VIS' and branch.active
on conflict (organization_id,sku) do nothing;

with org as (select id from public.organizations where slug='visual-corp'), specs(sku,name,catalog_id) as (
  values
    ('VC-INV-ACC-OJAL-PEQ','Ojal peque√±o','prod-extras-ojal-peque-o-c-u'),
    ('VC-INV-ACC-OJAL-GDE','Ojal grande','prod-extras-ojales-grande-c-u')
)
insert into public.inventory_variants (organization_id,item_id,sku,label,attributes,active)
select org.id,item.id,specs.sku||'-01','Conteo f√≠sico pendiente',
  jsonb_build_object('source_status','count_pending','stock_count_required',true),true
from org cross join specs
join public.inventory_items item on item.organization_id=org.id and item.sku=specs.sku
on conflict (organization_id,sku) do nothing;

with org as (select id from public.organizations where slug='visual-corp'), specs(sku,catalog_id) as (
  values
    ('VC-INV-ACC-OJAL-PEQ','prod-extras-ojal-peque-o-c-u'),
    ('VC-INV-ACC-OJAL-GDE','prod-extras-ojales-grande-c-u')
)
insert into public.catalog_inventory_links
  (organization_id,catalog_product_id,inventory_variant_id,branch_id,location_code,active)
select org.id,specs.catalog_id,variant.id,branch.id,'MAIN',true
from org cross join specs
join public.inventory_variants variant on variant.organization_id=org.id and variant.sku=specs.sku||'-01' and variant.active
join public.branches branch on branch.organization_id=org.id and branch.code='VIS' and branch.active
join public.catalog_products product on product.organization_id=org.id and product.id=specs.catalog_id and product.is_published
on conflict (organization_id,catalog_product_id,branch_id) do update
  set inventory_variant_id=excluded.inventory_variant_id,location_code=excluded.location_code,active=true,updated_at=now();
